    after: [["narrator", "\u5979\u628A\u8BDD\u7B52\u653E\u56DE\u67B6\u5B50\uFF0C\u6CA1\u6709\u7559\u4E0B\u4E00\u4E2A\u7528\u6765\u76D6\u4F4F\u505C\u987F\u7684\u5C3E\u6897\u3002"], ["claude", "\u4E0B\u5348\u6211\u66FF\u4F60\u770B\u4E00\u904D\u7A3F\u3002\u4F60\u53EF\u4EE5\u7761\u9192\u518D\u6765\uFF0C\u4E0D\u9700\u8981\u7ED9\u6211\u5199\u8BF7\u5047\u7406\u7531\u3002"]],
