var STORY_STORAGE_KEY = "model-router:gal-story:v1";
var episodeStorageKey = (baseKey, episodeId) => {
  if (episodeId === "legacy") return baseKey;
  if (STORY_EPISODES.some((episode) => episode.id === episodeId)) return `${baseKey}:episode:${episodeId}`;
  throw new Error("\u672A\u77E5\u7684\u5267\u60C5\u5267\u76EE\u3002");
};
var storySlotsKey = (baseKey, episodeId) => ["legacy"].includes(episodeId) ? baseKey : episodeStorageKey(baseKey, episodeId);
function selectedStoryEpisode(storage, baseKey = STORY_STORAGE_KEY) {
  const selected = storage?.getItem(`${baseKey}:episode`);
  if (STORY_EPISODES.some((episode) => episode.id === selected)) return selected;
  try {
    const existing = JSON.parse(storage?.getItem(baseKey) || "null");
    if (existing?.version === 1) return "legacy";
  } catch {
  }
  return "echo-chronicle";
}
function validateEpisode(state, episodeId) {
  if (episodeId && getStoryEpisode(state).id !== episodeId) throw new Error("\u5B58\u6863\u5C5E\u4E8E\u53E6\u4E00\u90E8\u5267\u76EE\uFF0C\u8BF7\u5148\u5207\u6362\u5267\u76EE\u518D\u5BFC\u5165\u3002");
  return state;
}
function readStory(storage, key = STORY_STORAGE_KEY, episodeId = null) {
  const source = storage?.getItem(key);
  if (!source) return createStory3(episodeId || "echo-chronicle");
  try {
    return validateEpisode(normalizeStory3(JSON.parse(source)), episodeId);
  } catch {
    throw new Error("\u5267\u60C5\u5B58\u6863\u65E0\u6CD5\u8BFB\u53D6\uFF0C\u539F\u5B58\u6863\u5DF2\u4FDD\u7559\u3002\u53EF\u5BFC\u5165\u5907\u4EFD\u6216\u91CD\u65B0\u5F00\u59CB\u3002");
  }
}
function writeStory(storage, key, state, episodeId = null) {
  if (!storage) throw new Error("\u6D4F\u89C8\u5668\u5B58\u50A8\u4E0D\u53EF\u7528\uFF0C\u8BF7\u5BFC\u51FA\u5267\u60C5\u5B58\u6863\u3002");
  storage.setItem(key, JSON.stringify(validateEpisode(normalizeStory3(state), episodeId)));
}
function readStorySlots(storage, key = STORY_STORAGE_KEY, episodeId = null) {
  const raw = JSON.parse(storage?.getItem(`${key}:slots`) || "[]");
  if (!Array.isArray(raw)) throw new Error("\u5267\u60C5\u624B\u52A8\u5B58\u6863\u65E0\u6CD5\u8BFB\u53D6\u3002");
  return Array.from({ length: 3 }, (_, index) => {
    const slot = raw[index];
    if (!slot) return null;
    try {
      return { state: validateEpisode(normalizeStory3(slot.state), episodeId), savedAt: typeof slot.savedAt === "string" ? slot.savedAt : "" };
    } catch {
      return { invalid: true };
    }
  });
}

